    iconTitle: 'Icon buttons', iconRule: 'Use only when meaning is highly familiar in context. Icon-only buttons need accessible names; pair unfamiliar or infrequent functions with text.', plus: 'Add', power: 'Start', more: 'More', groupTitle: 'Button groups', groupRule: 'Group peer actions with no more than three visible choices. Keep the primary action stable and separate dangerous actions from frequent ones.', start: 'Start', pause: 'Pause', cancel: 'Cancel', confirm: 'Confirm',
    apiTitle: 'API', apiIntro: 'Configurable properties for the Button component. Implementations should preserve the semantics, hierarchy, and interaction feedback defined in this guideline.', apiName: 'Property', apiDescription: 'Description', apiType: 'Type', apiDefault: 'Default',
    adaptiveTitle: 'Display & hardware adaptation', tft: 'TFT touchscreen', tftDesc: 'Keep full labels, icons, and states; anchor the primary action in the main thumb or sight zone.', led: 'LED / segment display', ledDesc: 'Do not copy visual material. Map actions to fixed backlit labels or physical keys on the same side as TFT.', knob: 'Knob / remote', knobDesc: 'Use a high-contrast focus ring. Rotate to move and press to confirm; focus must not jump automatically.', narrow: 'Narrow / strip display', narrowDesc: 'Keep the action label before decorative icons. Use full-width buttons when needed without shrinking the target.',
