    anatomyTitle:'Anatomy', anatomyIntro:'Tabs contain a tab list, tab items, text labels, a selection indicator, and a content panel. Icons, badges, and close controls are optional and should appear only when they add real value.', tablist:'Tab list', tab:'Tab item', label:'Text label', indicator:'Selection indicator', panel:'Content panel',
