  <section class="glass-panel p-6 md:p-10 mb-8"><h2 class="text-2xl font-bold mb-2">${copy.sizeTitle}</h2><p class="text-sm text-gray-500 mb-6">${copy.sizeIntro}</p><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-sm"><thead><tr class="border-b text-left text-gray-500">${copy.tableHead.map(x=>`<th class="py-3 pr-5">${x}</th>`).join('')}</tr></thead><tbody>${copy.rows.map((r,i)=>`<tr class="${i<2?'border-b':''}">${r.map((x,j)=>`<td class="py-4 pr-5 ${j===0?'font-semibold':'text-gray-600'}">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>
